css:
.card {
  position: relative;
  overflow: hidden; /* clip the ribbon to the corner */
  max-width: 280px;
  margin: 16px;
  padding: 32px 16px 16px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
  background: #fff;
}

.ribbon {
  position: absolute;
  top: 0;
  right: 0;
  z-index: 1;
  padding: 4px 12px;
  border-bottom-left-radius: 6px;
  background: #f97316;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
}

.title,
.text {
  margin: 0;
}

.title {
  font-weight: 600;
}

.text {
  margin-top: 8px;
  color: #52525b;
}
